function parseRequestedSuite(argv) {
  const suiteArg = argv.find((arg) => arg.startsWith("--suite="));
  if (suiteArg) return suiteArg.slice("--suite=".length);
  const suiteIndex = argv.indexOf("--suite");
  if (suiteIndex === -1) return null;
  return argv[suiteIndex + 1] ?? "";
}

function parseRequestedCliScope(argv) {
  const scopeArg = argv.find((arg) => arg.startsWith("--cli-scope="));
  if (scopeArg) return scopeArg.slice("--cli-scope=".length);
  const scopeIndex = argv.indexOf("--cli-scope");
  if (scopeIndex === -1) return null;
  return argv[scopeIndex + 1] ?? "";
}

function renderScenarioExecutionSummary(summary) {
  const { renderValidationSummary } = require(path.join(projectRoot, "dist", "cli", "render", "validationSummaryRenderer.js"));
  return renderValidationSummary(summary);
}

function runScenarioSuite(suiteName, options = {}) {
  const cliScope = options.cliScope ?? null;
  const allSuites = Object.keys(scenarioSuites).sort();
  if (cliScope !== null && suiteName !== "cli") {
    console.log(`FAIL scenario-suite-${suiteName}`);
    console.log("  --cli-scope can only be used with --suite cli.");
    return 1;
  }
  let suite = scenarioSuites[suiteName];
  if (!suite) {
    console.log(`FAIL scenario-suite-${suiteName}`);
    console.log(`  Unknown suite. Expected one of: ${allSuites.join(", ")}`);
    return 1;
  }
  try {
    if (suiteName === "cli") {
      suite = selectCliScenarioChecks(cliScope);
    }
  } catch (error) {
    console.log(`FAIL scenario-suite-${suiteName}`);
    console.log(`  ${error instanceof Error ? error.message : String(error)}`);
    return 1;
  }
  let failed = 0;
  let passed = 0;
  for (const check of suite) {
    if (check()) passed += 1;
    else failed += 1;
  }
  console.log(renderScenarioExecutionSummary({
    suitesExecuted: [suiteName],
    suitesSkipped: allSuites.filter((name) => name !== suiteName),
    totalChecks: suite.length,
    passedChecks: passed,
    failedChecks: failed,
    executionDurationMs: 0
  }));
  if (suiteName === "cli") {
    console.log(renderCliScopeExecutionSummary({
      scope: cliScope ?? "all",
      checksSelected: suite.length,
      checksPassed: passed,
      checksFailed: failed
    }));
  }
  return failed;
}

function runCliHelpCommand(args, cwd = projectRoot) {
  return spawnSync(process.execPath, [cliPath, ...args], {
    cwd,
    encoding: "utf8"
  });
}

function assertHelpIncludes(output, needles) {
  for (const needle of needles) {
    if (!output.includes(needle)) {
      throw new Error(`help output missing ${needle}: ${output}`);
    }
  }
}

function runCliHelpMainUnit() {
  const { renderMainHelp } = require(path.join(projectRoot, "dist", "cliHelp.js"));
  try {
    const direct = renderMainHelp();
    const cliResult = runCliHelpCommand(["--help"]);
    const helpCommand = runCliHelpCommand(["help"]);
    if (cliResult.status !== 0 || helpCommand.status !== 0 || cliResult.stdout !== direct || helpCommand.stdout !== direct) {
      throw new Error(`main help mismatch: direct=${direct} stdout=${cliResult.stdout} help=${helpCommand.stdout}`);
    }
    assertHelpIncludes(direct, [
      "# AI Software Factory CLI",
      "node dist/cli.js <command> [options]",
      "runs        Show historical governance run dashboard",
      "Governance inspection commands are read-only unless --export, --archive, or evidence-pack is explicitly used.",
      "Governance commands do not modify repair behavior."
    ]);

    console.log("PASS cli-help-main-unit");
    return true;
  } catch (error) {
    console.log("FAIL cli-help-main-unit");
    console.log(`  ${error instanceof Error ? error.message : String(error)}`);
    return false;
  }
}

